fault_detection.code:
IF timer_1Hz THEN
  raw = read_sensor();
  IF raw_error THEN state = ERROR; BREAK;
  val = filter(raw);
  temp = convert_units(val);
  IF temp < 0 OR temp > 60 THEN count++; IF count >= 3 state = FAULT;
  ELSE IF temp < 10 OR temp > 40 THEN count++; IF count >= 3 state = WARNING;
  ELSE count = 0; state = NORMAL;
  report(state, temp);
ENDIF
